const phrases=Object.entries({...CONTENT_EN,...UI_EN}).sort((a,b)=>b[0].length-a[0].length);

// Only human-facing text and accessibility labels are localized. Values, IDs,
// dataset attributes, save payloads and user-entered content are untouched.
export function translateUIEnglish(value){
 const original=String(value??'');if(!/[가-힣]/.test(original))return original;
 const leading=original.match(/^\s*/)?.[0]??'',trailing=original.match(/\s*$/)?.[0]??'',trimmed=original.trim();
 if(Object.hasOwn(UI_EN,trimmed))return leading+UI_EN[trimmed]+trailing;
 const domain=englishText(trimmed);if(domain!==trimmed)return leading+domain+trailing;
 let out=trimmed;
 out=out.replace(/(\d+(?:\.\d+)?)천만원/g,(_,n)=>'$'+(Number(n)*25000).toLocaleString('en-US')).replace(/(\d+(?:\.\d+)?)만원/g,(_,n)=>'$'+Math.round(Number(n)*25).toLocaleString('en-US'));
 out=out.replace(/현재\s*(\d+)세/g,'Age $1').replace(/(\d+)세/g,'$1 years old');
 out=out.replace(/(\d+)주차/g,'Week $1').replace(/학사\s*(\d+)주/g,'academic week $1').replace(/(\d+)개월 연속 · 운영 종료까지 남은 (\d+)개월/g,'$1 consecutive months · $2 months to closure');
 out=out.replace(/다음 (?:3|9)월에 조정/g,'review next September').replace(/인건비 계상률은 매년 3월, 운영 집행은 매달 조정합니다\./g,'Stipend allocation changes each September; operations can change each month.');
 out=out.replace(/이번 달 (\d+)주 · 클릭해서 학생의 제안을 조정합니다\./g,'$1 weeks this month · adjust the student’s proposal.');
 out=out.replace(/(\d+)개 완료/g,'$1 completed').replace(/보관한 저장점 (\d+)개/g,'Saved checkpoints: $1').replace(/주요 후일담 (\d+) \/ (\d+)/g,'Main epilogues $1 / $2').replace(/^(\d+)건$/,'$1 letters');
 out=out.replace(/부족액 (\$[\d,]+) 자동 차입/g,'Automatic advance for a $1 shortfall').replace(/이번 역할의 신규 과제 · 선정 시 연간 예정액 (\$[\d,]+)/g,'New award for this role · projected annual amount if selected: $1');
 out=out.replace(/시작 연구비 최소 (\$[\d,]+) · 정착지원 첫 (\d+)개월/g,'Startup funding floor $1 · support during the first $2 months');
 out=out.replace(/필수 인건비·실험실 유지비가 부족한 달에만 정착지원 · 이번 달 최대 (\$[\d,]+), 남은 한도 (\$[\d,]+)/g,'Support applies only to essential shortfalls · this month’s cap $1; remaining allowance $2');
 out=out.replace(/(이번 달|다음 달) (January|February|March|April|May|June|July|August|September|October|November|December) 국내학회 참석 계획/g,(_,when,month)=>`${when==='이번 달'?'This month’s':'Next month’s'} regional conference · ${month}`);
 out=out.replace(/(이번 달|다음 달) (January|February|March|April|May|June|July|August|September|October|November|December) 셋째 주 학술대회에 누가 참석할지 정한다\. 학생은 학부 과정에서는 청강·현장 학습, 대학원에서는 연구 준비도에 맞춰 발표를 준비한다\. 참석 경비는 실제 참석 월에 집행한다\./g,(_,when,month)=>`Choose who attends the conference in week three of ${month}. Undergraduates attend to learn; graduate students prepare to present when their research is ready. Expenses are charged in the month of attendance.`);
 out=out.replace(/보낸 사람: (.*?) · 받는 사람: 지도교수/g,'From: $1 · To: faculty advisor').replace(/(.*?)으로 돌아갈까요\?/g,'Restore $1?');
 out=out.replace(/(\d+)개월 남음/g,'$1 months remaining').replace(/업무 반영 (\d+)%/g,'Workload effectiveness $1%');
 out=out.replace(/학과 차입 (\$[\d,]+)으로 운영을 이어 갔습니다\./g,'A departmental advance of $1 kept operations running.').replace(/운영비 (\$[\d,]+) · 교수 에너지 (\d+) · 학술활동·연구실 운영 및 교류/g,'Operating cost $1 · faculty energy $2 · scholarship, lab operations and networking').replace(/운영비 (\$[\d,]+) · 교수 에너지 (\d+) · 학습·교류/g,'Operating cost $1 · faculty energy $2 · learning and networking');
 out=out.replace(/(\d+)주 회복 시간을 확보하기로 했다\./g,'Agreed to protect $1 weeks of recovery.').replace(/연구 계획을 유지하기로 했다\. 학생의 부담과 스트레스가 커졌다\./g,'Kept the research plan. The student’s strain and stress increased.').replace(/연구를 멈추고 쉬었다\./g,'Paused research for recovery.').replace(/해외 연구년 중 국내 참석을 (.*?)에서 (.*?)로 조정했다\./g,'While visiting abroad, changed regional conference attendance from $1 to $2.');
 out=out.replace(/^(.+)에 업무 크레딧을 다시 배분하세요\./,'Reallocate workload credits to $1.');
 for(const [ko,en] of phrases)if(out.includes(ko))out=out.split(ko).join(en);
 out=out.replace(/(\d+)개월/g,'$1 months').replace(/(\d+)주 수행/g,'$1 weeks completed').replace(/(\d+)주/g,'$1 weeks').replace(/(\d+)년/g,'$1 years').replace(/(\d+)회/g,'$1 times');
 return leading+out+trailing;
}
const protectedSelectors='script,style,textarea,input,[contenteditable="true"],[data-user-text],.utility-user,.student-id h2,.student-speaker,.mail-sender,.candidate-heading strong,.scholar-identity h2,.faculty-scroll-summary strong,.checkpoint-list strong,.edition-link';
export function localizeEnglishUI(root){
 if(!root)return;const document=root.ownerDocument??root;
 const walker=document.createTreeWalker(root,4);let node;
 while((node=walker.nextNode())){if(node.parentElement?.closest(protectedSelectors))continue;const text=node.nodeValue;if(text&&/[가-힣]/.test(text))node.nodeValue=translateUIEnglish(text);}
 const elements=root.querySelectorAll?.('[aria-label],[title],[placeholder],optgroup[label],img[alt]')??[];
 for(const element of elements){if(element.closest('[data-user-text],.edition-link'))continue;for(const attr of ['aria-label','title','placeholder','label','alt'])if(element.hasAttribute(attr)){const text=element.getAttribute(attr);if(/[가-힣]/.test(text))element.setAttribute(attr,translateUIEnglish(text));}}
}
